    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "name" VARCHAR(64) DEFAULT 'O''Reilly',
    "amount" DECIMAL(12,2),
    PRIMARY KEY ("id")
);
